function AddSource(){
  const navigate=useNavigate(),[url,setUrl]=useState(''),[analysis,setAnalysis]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const analyze=async e=>{e.preventDefault();setBusy(true);setError('');try{const r=await api.post('/sources/analyze',{url});setAnalysis({...r.data,frequency:'daily',crawl_delay:2})}catch(x){setError(x.response?.data?.detail||x.message)}finally{setBusy(false)}}
  const start=async()=>{setBusy(true);setError('');try{const r=await api.post('/sources',{name:analysis.name,base_url:analysis.url,source_type:analysis.source_type,input_kind:analysis.input_kind,frequency:analysis.frequency,crawl_delay:Number(analysis.crawl_delay),requires_javascript:analysis.requires_javascript,enabled:true});await api.post(`/scrapers/${r.data.id}/run`);navigate('/admin/sources')}catch(x){setError(x.response?.data?.detail||x.message)}finally{setBusy(false)}}
  return <><Link to="/admin/sources" className="mb-5 inline-flex items-center gap-2 text-xs text-[#708079]"><ArrowLeft size={14}/>Back to sources</Link><PageHead eyebrow="Source discovery" title="Add data source" description="Analyze a public URL, confirm its detected type, and begin collection."/><div className="mx-auto max-w-2xl"><form onSubmit={analyze} className="panel p-6"><label className="label">Source URL</label><div className="mt-2 flex gap-2"><input required type="url" value={url} onChange={e=>setUrl(e.target.value)} className="input min-w-0 flex-1" placeholder="https://____________________________"/><button disabled={busy} className="btn btn-primary px-5">{busy?<RefreshCw className="animate-spin" size={14}/>:<SearchIcon size={14}/>}Analyze source</button></div><p className="mt-3 text-[11px] leading-5 text-[#68776f]">Supports government websites and PDFs, tender portals, news sites and articles, YouTube videos, channels, and playlists.</p>{error&&<div className="mt-4 rounded-lg bg-red-400/10 p-3 text-xs text-red-300">{error}</div>}</form>{analysis&&<section className="panel mt-5 p-6"><div className="mb-5 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-lg bg-[#56c88d]/10 text-[#68d49a]"><CheckCircle2 size={18}/></div><div><div className="font-semibold">Source detected</div><div className="mt-1 text-xs text-[#68776f]">Review before starting the collector</div></div></div><div className="grid gap-4 sm:grid-cols-2"><label className="sm:col-span-2"><span className="label">Name</span><input value={analysis.name} onChange={e=>setAnalysis({...analysis,name:e.target.value})} className="input mt-2 w-full"/></label><label><span className="label">Detected type</span><select value={analysis.source_type} onChange={e=>setAnalysis({...analysis,source_type:e.target.value})} className="input mt-2 w-full">{['government_website','government_document','tender_portal','gazette','court','audit','news','youtube'].map(x=><option value={x} key={x}>{titleCase(x)}</option>)}</select></label><label><span className="label">Input kind</span><input readOnly value={analysis.input_kind} className="input mt-2 w-full opacity-70"/></label><label><span className="label">Frequency</span><select value={analysis.frequency} onChange={e=>setAnalysis({...analysis,frequency:e.target.value})} className="input mt-2 w-full"><option>every 30 minutes</option><option>hourly</option><option>every 6 hours</option><option>daily</option><option>weekly</option></select></label><label><span className="label">Crawl delay</span><input type="number" min="0.5" max="120" step="0.5" value={analysis.crawl_delay} onChange={e=>setAnalysis({...analysis,crawl_delay:e.target.value})} className="input mt-2 w-full"/></label></div><div className="mt-6 flex items-center justify-between"><span className="text-[11px] text-[#68776f]">JavaScript: {analysis.requires_javascript?'Playwright required':'Not required'}</span><button onClick={start} disabled={busy} className="btn btn-primary"><Play size={14}/>Start scraping</button></div></section>}</div></>
}

function SettingsPage(){return <><PageHead eyebrow="Workspace" title="Platform settings" description="Storage, retention, collection identity, and indexing defaults."/><div className="grid gap-5 lg:grid-cols-2"><section className="panel p-6"><div className="mb-5 flex items-center gap-3"><Server className="text-[#64d095]" size={19}/><div><div className="font-semibold">Storage</div><div className="text-xs text-[#68776f]">Local now, S3-compatible when configured</div></div></div>{[['Storage driver','Local filesystem'],['Content path','./storage'],['Version retention','Keep forever'],['Hash algorithm','SHA256']].map(([k,v])=><div className="flex justify-between border-t border-white/[.05] py-4 text-xs" key={k}><span className="text-[#6d7b74]">{k}</span><span>{v}</span></div>)}</section><section className="panel p-6"><div className="mb-5 flex items-center gap-3"><ShieldCheck className="text-[#64d095]" size={19}/><div><div className="font-semibold">Collection safety</div><div className="text-xs text-[#68776f]">Applied to all scraper modules</div></div></div>{['Respect robots.txt','Enforce crawl delays','Exponential retries: 2s, 4s, 8s','Never bypass authentication or paywalls','Public content only'].map(x=><div className="flex items-center gap-3 border-t border-white/[.05] py-3 text-xs text-[#a9b6af]" key={x}><CheckCircle2 size={14} className="text-[#5dce90]"/>{x}</div>)}</section></div></>}

function AdminRoutes(){return <Routes><Route index element={<Dashboard/>}/><Route path="sources" element={<Sources/>}/><Route path="sources/add" element={<AddSource/>}/><Route path="documents" element={<Documents/>}/><Route path="documents/:id" element={<DocumentDetail/>}/><Route path="youtube" element={<YoutubeList/>}/><Route path="youtube/:id" element={<VideoDetail/>}/><Route path="news" element={<News/>}/><Route path="news/:id" element={<NewsDetail/>}/><Route path="scrapers" element={<Scrapers/>}/><Route path="scrapers/:id" element={<ScraperDetail/>}/><Route path="runs" element={<Scrapers/>}/><Route path="logs" element={<Logs/>}/><Route path="settings" element={<SettingsPage/>}/><Route path="*" element={<Navigate to="/admin"/>}/></Routes>}
function LegacyScraperRedirect(){const {id}=useParams();return <Navigate to={`/admin/scrapers/${id}`} replace/>}

export default function App(){return <Routes><Route element={<PublicLayout/>}><Route index element={<Home/>}/><Route path="search" element={<SearchPage/>}/><Route path="documents/:id" element={<PublicDocument/>}/><Route path="youtube/:id" element={<PublicVideo/>}/><Route path="news/:id" element={<PublicNews/>}/></Route><Route path="admin/*" element={<Layout><AdminRoutes/></Layout>}/><Route path="sources" element={<Navigate to="/admin/sources"/>}/><Route path="scrapers" element={<Navigate to="/admin/scrapers"/>}/><Route path="scrapers/:id" element={<LegacyScraperRedirect/>}/><Route path="logs" element={<Navigate to="/admin/logs"/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes>}
